      alt: "Billete especimen de Quinientos Pesos Oro de El Banco de la República, Colombia, fechado 7 de agosto de 1947, con retrato militar y medallón de la Libertad en el reverso"
    },
    {
      key: "1984",
      label: "Quinientos Pesos Oro \u00b7 20 de julio de 1984",
      denomination: "Quinientos Pesos Oro",
      date: "20 de julio de 1984",
      obverse: "Multicolor, predomina el rojo. Retrato de Francisco de Paula Santander a la izquierda. Leyenda: \u201cEL BANCO DE LA REP\u00daBLICA PAGAR\u00c1 AL PORTADOR QUINIENTOS PESOS ORO\u201d. Sobreimpresi\u00f3n roja \u201cSPECIMEN\u201d. Numeraci\u00f3n en ceros (00000000). Firmas de Gerente y Abogado Subgerente.",
      reverse: "Multicolor. Vi\u00f1eta de la Casa de la Moneda de Bogot\u00e1, con el escudo de Colombia y el medall\u00f3n de la Libertad. Texto: \u201cQUINIENTOS PESOS ORO\u201d. Sobreimpresi\u00f3n roja \u201cSPECIMEN\u201d.",
      condition: "Gema sin circular, con perforaciones de cancelaci\u00f3n caracter\u00edsticas. Tonos rojos intensos y excelente detalle arquitect\u00f3nico.",
      rarity: "Primer a\u00f1o de la serie renovada con Santander y la Casa de la Moneda.",
      description: "Espécimen que introduce el dise\u00f1o duradero con Santander en el anverso y la Casa de la Moneda de Bogot\u00e1 en el reverso, todav\u00eda con la sobreimpresi\u00f3n en ingl\u00e9s \u201cSPECIMEN\u201d.",
      jpg: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1984-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1984-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1984-specimen-640.webp",
      alt: "Billete especimen de Quinientos Pesos Oro de El Banco de la República, Colombia, fechado 20 de julio de 1984, anverso con el retrato de Francisco de Paula Santander y reverso con la Casa de la Moneda de Bogotá"
    },
    {
      key: "1989",
      label: "Quinientos Pesos Oro \u00b7 20 de julio de 1989",
      denomination: "Quinientos Pesos Oro",
      date: "20 de julio de 1989",
      obverse: "Multicolor, predomina el rojo. Retrato de Francisco de Paula Santander a la izquierda. Leyenda: \u201cEL BANCO DE LA REP\u00daBLICA PAGAR\u00c1 AL PORTADOR QUINIENTOS PESOS ORO\u201d. Sobreimpresi\u00f3n roja \u201cMUESTRA SIN VALOR\u201d. Numeraci\u00f3n en ceros (00000000). Firmas de Gerente y Abogado Subgerente.",
      reverse: "Multicolor. Vi\u00f1eta de la Casa de la Moneda de Bogot\u00e1, con el escudo de Colombia y el medall\u00f3n de la Libertad. Texto: \u201cQUINIENTOS PESOS ORO\u201d. Sobreimpresi\u00f3n roja \u201cMUESTRA SIN VALOR\u201d.",
      condition: "Gema sin circular, con perforaciones de cancelaci\u00f3n caracter\u00edsticas. Colores vibrantes.",
      rarity: "Ejemplar de transici\u00f3n hacia la sobreimpresi\u00f3n castellana, cinco a\u00f1os despu\u00e9s de la introducci\u00f3n del dise\u00f1o.",
      description: "Espécimen que repite el dise\u00f1o de 1984 con la misma vi\u00f1eta de la Casa de la Moneda, ya con la leyenda castellana \u201cMUESTRA SIN VALOR\u201d.",
      jpg: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1989-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1989-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1989-specimen-640.webp",
      alt: "Billete especimen de Quinientos Pesos Oro de El Banco de la República, Colombia, fechado 20 de julio de 1989, anverso con el retrato de Francisco de Paula Santander y reverso con la Casa de la Moneda de Bogotá"
    },
    {
      key: "1993",
      label: "Quinientos Pesos Oro \u00b7 4 de enero de 1993",
      denomination: "Quinientos Pesos Oro",
      date: "4 de enero de 1993",
      obverse: "Multicolor, predomina el rojo. Retrato de Francisco de Paula Santander a la izquierda. Leyenda: \u201cEL BANCO DE LA REP\u00daBLICA PAGAR\u00c1 AL PORTADOR QUINIENTOS PESOS ORO\u201d. Sobreimpresi\u00f3n roja \u201cMUESTRA SIN VALOR\u201d. Numeraci\u00f3n en ceros (00000000). Santa Fe de Bogot\u00e1, 4 de enero de 1993.",
      reverse: "Multicolor. Vi\u00f1eta de la Casa de la Moneda de Bogot\u00e1, con el escudo de Colombia y el medall\u00f3n de la Libertad. Texto: \u201cQUINIENTOS PESOS ORO\u201d. Sobreimpresi\u00f3n roja \u201cMUESTRA SIN VALOR\u201d.",
      condition: "Gema sin circular, con perforaciones de cancelaci\u00f3n caracter\u00edsticas. Papel y grabado refinados.",
      rarity: "Ejemplar m\u00e1s tard\u00edo de la serie, con la denominaci\u00f3n de la ciudad ya como \u201cSanta Fe de Bogot\u00e1\u201d.",
      description: "Espécimen final de esta serie, casi id\u00e9ntico a los de 1984 y 1989 salvo por la fecha y refinamientos menores de seguridad.",
      jpg: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1993-specimen.jpg",
      webp: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1993-specimen.webp",
      webp640: "uploads/colombia-banco-de-la-republica-500-pesos-oro-1993-specimen-640.webp",
      alt: "Billete especimen de Quinientos Pesos Oro de El Banco de la República, Colombia, fechado 4 de enero de 1993, anverso con el retrato de Francisco de Paula Santander y reverso con la Casa de la Moneda de Bogotá"
    }
  ];

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  openZoomAt = (index) => {
    this.setState({ zoomIndex: index, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomIndex: null });
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomIndex !== null) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    const notes = this.noteData.map((n, i) => Object.assign({}, n, { openZoom: () => this.openZoomAt(i) }));
    const active = s.zoomIndex !== null ? this.noteData[s.zoomIndex] : null;

    return {
      notes,
      zoomIndex: s.zoomIndex !== null,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      activeNoteJpg: active ? active.jpg : "",
      activeNoteWebp: active ? active.webp : ""
    };
  }
}
